/**
 * Muny database schema (v1: Phase 1 ledger).
 *
 * Conventions (see docs/ARCHITECTURE.md):
 * - Money: integer minor units (cents) in `*_cents` columns + ISO currency code.
 * - Posted dates: ISO `YYYY-MM-DD` text. Event timestamps: unix epoch ms integers.
 * - IDs: time-sortable random text ids generated by the app (see id.ts).
 * - Later phases (recurring series, budgets, savings, agent tokens...) add tables
 *   through new migrations; never edit an applied migration.
 */
import { sql } from "drizzle-orm";
import {
  type AnySQLiteColumn,
  blob,
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";

const nowMs = sql`(cast(unixepoch('subsec') * 1000 as integer))`;
const createdAt = () => integer({ mode: "timestamp_ms" }).notNull().default(nowMs);
const updatedAt = () =>
  integer({ mode: "timestamp_ms" })
    .notNull()
    .default(nowMs)
    .$onUpdate(() => new Date());

// ---------------------------------------------------------------------------
// Users & sessions
// ---------------------------------------------------------------------------

export const users = sqliteTable("users", {
  id: text().primaryKey(),
  email: text().notNull().unique(),
  displayName: text(),
  passwordHash: text().notNull(),
  /** owner: everything; member: everything but household & backups; viewer: read-only. */
  role: text({ enum: ["owner", "member", "viewer"] })
    .notNull()
    .default("member"),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** Single-use household invite links. Only the token's hash is stored. */
export const invites = sqliteTable("invites", {
  id: text().primaryKey(),
  tokenHash: text().notNull().unique(),
  role: text({ enum: ["member", "viewer"] }).notNull(),
  createdBy: text().references(() => users.id, { onDelete: "set null" }),
  expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
  usedAt: integer({ mode: "timestamp_ms" }),
  usedBy: text().references(() => users.id, { onDelete: "set null" }),
  createdAt: createdAt(),
});

export const sessions = sqliteTable(
  "sessions",
  {
    /** SHA-256 of the session token; the raw token only lives in the cookie. */
    idHash: text().primaryKey(),
    userId: text()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("sessions_user_idx").on(t.userId)],
);

// ---------------------------------------------------------------------------
// Connections & accounts
// ---------------------------------------------------------------------------

export const connections = sqliteTable("connections", {
  id: text().primaryKey(),
  provider: text({ enum: ["manual", "file", "plaid", "teller", "simplefin"] }).notNull(),
  institutionName: text(),
  /** Provider-side id (Plaid item_id, Teller enrollment id...). */
  providerRef: text(),
  /** AES-256-GCM encrypted JSON blob (access tokens etc). Never logged. */
  credentialsEnc: text(),
  status: text({ enum: ["pending_setup", "active", "error", "reauth_required", "disabled"] })
    .notNull()
    .default("active"),
  lastSyncAt: integer({ mode: "timestamp_ms" }),
  lastError: text(),
  /** Provider sync position (Plaid transactions/sync cursor). Not secret. */
  syncCursor: text(),
  /** Provider account ids the user chose not to track. */
  ignoredAccountRefs: text({ mode: "json" }).$type<string[]>().notNull().default(sql`'[]'`),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const accounts = sqliteTable(
  "accounts",
  {
    id: text().primaryKey(),
    connectionId: text().references(() => connections.id, { onDelete: "set null" }),
    providerAccountRef: text(),
    name: text().notNull(),
    institutionName: text(),
    type: text({
      enum: ["checking", "savings", "credit", "loan", "investment", "cash", "asset", "other"],
    }).notNull(),
    /** Last 4 digits only, never the full number. */
    mask: text(),
    currency: text().notNull().default("USD"),
    /**
     * How the balance is determined:
     * - computed: openingBalanceCents + sum(posted transactions). Manual/file accounts.
     * - reported: currentBalanceCents as reported by a sync provider.
     */
    balanceSource: text({ enum: ["computed", "reported"] })
      .notNull()
      .default("computed"),
    /** Balance before the first recorded transaction (computed accounts). */
    openingBalanceCents: integer().notNull().default(0),
    /** Latest provider-reported balance (cents). History lives in balance_snapshots. */
    currentBalanceCents: integer(),
    hidden: integer({ mode: "boolean" }).notNull().default(false),
    /** Advertised interest rate you entered (APY in hundredths of a percent: 435 = 4.35%). */
    apyBps: integer(),
    /** Excluded from budgets/reports (e.g. a business account). */
    excludeFromReports: integer({ mode: "boolean" }).notNull().default(false),
    sortOrder: integer().notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("accounts_provider_ref_uq")
      .on(t.connectionId, t.providerAccountRef)
      .where(sql`${t.providerAccountRef} IS NOT NULL`),
  ],
);

export const balanceSnapshots = sqliteTable(
  "balance_snapshots",
  {
    accountId: text()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    /** YYYY-MM-DD */
    date: text().notNull(),
    balanceCents: integer().notNull(),
    /** Worked out (e.g. investments rebuilt from trades and past prices), not reported. */
    estimated: integer({ mode: "boolean" }).notNull().default(false),
  },
  (t) => [primaryKey({ columns: [t.accountId, t.date] })],
);

// ---------------------------------------------------------------------------
// Categories, payees, tags
// ---------------------------------------------------------------------------

export const categoryGroups = sqliteTable("category_groups", {
  id: text().primaryKey(),
  name: text().notNull().unique(),
  kind: text({ enum: ["expense", "income", "transfer"] })
    .notNull()
    .default("expense"),
  sortOrder: integer().notNull().default(0),
  createdAt: createdAt(),
});

export const categories = sqliteTable(
  "categories",
  {
    id: text().primaryKey(),
    groupId: text()
      .notNull()
      .references(() => categoryGroups.id, { onDelete: "restrict" }),
    name: text().notNull(),
    icon: text(),
    color: text(),
    hidden: integer({ mode: "boolean" }).notNull().default(false),
    sortOrder: integer().notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("categories_group_name_uq").on(t.groupId, t.name)],
);

export const payees = sqliteTable("payees", {
  id: text().primaryKey(),
  displayName: text().notNull().unique(),
  /** Default category applied to new transactions from this payee. */
  defaultCategoryId: text().references(() => categories.id, { onDelete: "set null" }),
  createdAt: createdAt(),
});

export const tags = sqliteTable("tags", {
  id: text().primaryKey(),
  name: text().notNull().unique(),
  color: text(),
});

// ---------------------------------------------------------------------------
// Imports & transactions
// ---------------------------------------------------------------------------

export const importBatches = sqliteTable("import_batches", {
  id: text().primaryKey(),
  source: text({ enum: ["csv", "ofx", "qfx", "rocket_money", "provider_sync"] }).notNull(),
  /** Original filename only; file contents are never stored. */
  filename: text(),
  accountId: text().references(() => accounts.id, { onDelete: "set null" }),
  rowsTotal: integer().notNull().default(0),
  rowsImported: integer().notNull().default(0),
  rowsDuplicate: integer().notNull().default(0),
  rowsFailed: integer().notNull().default(0),
  createdBy: text().references(() => users.id, { onDelete: "set null" }),
  createdAt: createdAt(),
});

export const transactions = sqliteTable(
  "transactions",
  {
    id: text().primaryKey(),
    accountId: text()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    /** YYYY-MM-DD */
    postedDate: text().notNull(),
    /** YYYY-MM-DD, when the bank reports an authorization date different from posting. */
    authorizedDate: text(),
    /** Signed minor units: negative = money out of the account. */
    amountCents: integer().notNull(),
    currency: text().notNull().default("USD"),
    rawDescription: text().notNull(),
    payeeId: text().references(() => payees.id, { onDelete: "set null" }),
    categoryId: text().references(() => categories.id, { onDelete: "set null" }),
    notes: text(),
    pending: integer({ mode: "boolean" }).notNull().default(false),
    /** Hidden transactions are excluded from budgets & reports. */
    hidden: integer({ mode: "boolean" }).notNull().default(false),
    /** Other side of a transfer between the user's own accounts. */
    transferPairId: text().references((): AnySQLiteColumn => transactions.id, {
      onDelete: "set null",
    }),
    /** Provider transaction id (Plaid/Teller) for idempotent sync. */
    providerTxnRef: text(),
    /** Stable dedupe hash: account + date + amount + normalized description + occurrence. */
    importHash: text().notNull(),
    importBatchId: text().references(() => importBatches.id, { onDelete: "set null" }),
    /** Recurring series (subscription/bill/income) this charge belongs to. */
    recurringSeriesId: text().references((): AnySQLiteColumn => recurringSeries.id, {
      onDelete: "set null",
    }),
    /** The user said this isn't a transfer; transfer detection leaves it alone. */
    notTransfer: integer({ mode: "boolean" }).notNull().default(false),
    /** True when the user edited category/payee manually (rules won't override). */
    userModified: integer({ mode: "boolean" }).notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("transactions_import_hash_uq").on(t.accountId, t.importHash),
    uniqueIndex("transactions_provider_ref_uq")
      .on(t.accountId, t.providerTxnRef)
      .where(sql`${t.providerTxnRef} IS NOT NULL`),
    index("transactions_posted_idx").on(t.postedDate),
    index("transactions_account_posted_idx").on(t.accountId, t.postedDate),
    index("transactions_category_idx").on(t.categoryId),
    index("transactions_payee_idx").on(t.payeeId),
  ],
);

export const transactionSplits = sqliteTable(
  "transaction_splits",
  {
    id: text().primaryKey(),
    transactionId: text()
      .notNull()
      .references(() => transactions.id, { onDelete: "cascade" }),
    categoryId: text().references(() => categories.id, { onDelete: "set null" }),
    amountCents: integer().notNull(),
    notes: text(),
  },
  (t) => [index("transaction_splits_txn_idx").on(t.transactionId)],
);

export const transactionTags = sqliteTable(
  "transaction_tags",
  {
    transactionId: text()
      .notNull()
      .references(() => transactions.id, { onDelete: "cascade" }),
    tagId: text()
      .notNull()
      .references(() => tags.id, { onDelete: "cascade" }),
  },
  (t) => [primaryKey({ columns: [t.transactionId, t.tagId] })],
);

// ---------------------------------------------------------------------------
// Rules
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Recurring charges
// ---------------------------------------------------------------------------

export const recurringSeries = sqliteTable(
  "recurring_series",
  {
    id: text().primaryKey(),
    name: text().notNull(),
    /** Merchant key used for detection (lower-cased merchant name). */
    matchKey: text().notNull(),
    direction: text({ enum: ["out", "in"] }).notNull(),
    /** Typical size of the charge (absolute cents), to tell a merchant's plans apart. */
    anchorCents: integer().notNull(),
    kind: text({ enum: ["subscription", "bill", "income"] }).notNull(),
    status: text({ enum: ["detected", "confirmed", "ignored", "cancelled"] })
      .notNull()
      .default("detected"),
    interval: text({
      enum: ["weekly", "biweekly", "monthly", "quarterly", "semiannual", "annual"],
    }).notNull(),
    /** Signed, Muny convention (negative = money out). */
    expectedAmountCents: integer().notNull(),
    fixedAmount: integer({ mode: "boolean" }).notNull().default(true),
    firstDate: text().notNull(),
    lastDate: text().notNull(),
    lastAmountCents: integer().notNull(),
    accountId: text().references(() => accounts.id, { onDelete: "set null" }),
    payeeId: text().references(() => payees.id, { onDelete: "set null" }),
    categoryId: text().references(() => categories.id, { onDelete: "set null" }),
    source: text({ enum: ["detected", "manual"] })
      .notNull()
      .default("detected"),
    /** The user changed name/kind/interval/amount; rescans keep their values. */
    userModified: integer({ mode: "boolean" }).notNull().default(false),
    /** YYYY-MM-DD the user marked it cancelled. */
    cancelledAt: text(),
    notes: text(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("recurring_series_key_idx").on(t.matchKey, t.direction)],
);

// ---------------------------------------------------------------------------
// Budgets
// ---------------------------------------------------------------------------

/** A monthly budget for one category, or the overall total (category_id null). */
export const budgets = sqliteTable(
  "budgets",
  {
    id: text().primaryKey(),
    categoryId: text().references(() => categories.id, { onDelete: "cascade" }),
    /**
     * What a budget without a category is for: "spending" (the total spending
     * budget), "income" (earnings target) or "bills" (recurring bills budget).
     * Category budgets are always "spending".
     */
    kind: text({ enum: ["spending", "income", "bills"] })
      .notNull()
      .default("spending"),
    /** Unspent money carries into next month (and overspending is deducted). */
    rollover: integer({ mode: "boolean" }).notNull().default(false),
    /** YYYY-MM: first month this budget applies (rollover starts counting here). */
    startMonth: text().notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("budgets_category_uq").on(t.categoryId).where(sql`${t.categoryId} IS NOT NULL`),
  ],
);

/** Budget amount history: the amount applies from from_month until the next row. */
export const budgetAmounts = sqliteTable(
  "budget_amounts",
  {
    budgetId: text()
      .notNull()
      .references(() => budgets.id, { onDelete: "cascade" }),
    /** YYYY-MM */
    fromMonth: text().notNull(),
    amountCents: integer().notNull(),
  },
  (t) => [primaryKey({ columns: [t.budgetId, t.fromMonth] })],
);

export const rules = sqliteTable("rules", {
  id: text().primaryKey(),
  name: text().notNull(),
  enabled: integer({ mode: "boolean" }).notNull().default(true),
  /** Lower runs first. */
  priority: integer().notNull().default(100),
  /** JSON: { all|any: [{ field, op, value }] }, validated by the app. */
  conditions: text({ mode: "json" }).notNull(),
  /** JSON: [{ type: setCategory|setPayee|addTag|hide|..., value }] */
  actions: text({ mode: "json" }).notNull(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------
// Settings & audit
// ---------------------------------------------------------------------------

export const appSettings = sqliteTable("app_settings", {
  key: text().primaryKey(),
  value: text({ mode: "json" }).notNull(),
  updatedAt: updatedAt(),
});

export const auditLog = sqliteTable(
  "audit_log",
  {
    id: integer().primaryKey({ autoIncrement: true }),
    at: createdAt(),
    actorType: text({ enum: ["user", "agent", "system"] }).notNull(),
    /** user id or api token id */
    actorId: text(),
    action: text().notNull(),
    entityType: text(),
    entityId: text(),
    /** JSON details. Must never contain secrets. */
    details: text({ mode: "json" }),
  },
  (t) => [
    index("audit_log_at_idx").on(t.at),
    index("audit_log_entity_idx").on(t.entityType, t.entityId),
  ],
);

// ---------------------------------------------------------------------------
// Alerts & notifications (Phase 3)
// ---------------------------------------------------------------------------

export const alertRules = sqliteTable("alert_rules", {
  id: text().primaryKey(),
  /** low_balance | large_transaction | unusual_charge | duplicate_charge | bill_due | price_increase | budget | charged_after_cancel | connection_error | trial_ending */
  type: text().notNull().unique(),
  enabled: integer({ mode: "boolean" }).notNull().default(true),
  /** JSON parameters for the type (thresholds etc.), validated by the app. */
  params: text({ mode: "json" }).notNull().default(sql`'{}'`),
  /** Also send to these channel ids (in-app is always on). */
  channelIds: text({ mode: "json" }).$type<string[]>().notNull().default(sql`'[]'`),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const notificationChannels = sqliteTable("notification_channels", {
  id: text().primaryKey(),
  type: text({ enum: ["ntfy", "apprise", "smtp", "webhook"] }).notNull(),
  name: text().notNull(),
  enabled: integer({ mode: "boolean" }).notNull().default(true),
  /** AES-256-GCM encrypted JSON config (URLs, tokens, SMTP password). Never logged. */
  configEnc: text().notNull(),
  lastSentAt: integer({ mode: "timestamp_ms" }),
  lastError: text(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const notifications = sqliteTable(
  "notifications",
  {
    id: text().primaryKey(),
    ruleType: text().notNull(),
    /** Same alert never fires twice: e.g. "bill_due:<series>:<date>". */
    dedupeKey: text().notNull().unique(),
    severity: text({ enum: ["info", "warning"] })
      .notNull()
      .default("info"),
    title: text().notNull(),
    body: text().notNull(),
    /** In-app path to open, e.g. /recurring. */
    link: text(),
    createdAt: createdAt(),
    readAt: integer({ mode: "timestamp_ms" }),
    /** When it was handed to the outbound channels (null = not yet / none). */
    sentAt: integer({ mode: "timestamp_ms" }),
  },
  (t) => [index("notifications_created_idx").on(t.createdAt)],
);

// ---------------------------------------------------------------------------
// Free trials (Phase 3)
// ---------------------------------------------------------------------------

export const trials = sqliteTable("trials", {
  id: text().primaryKey(),
  name: text().notNull(),
  /** YYYY-MM-DD */
  startDate: text().notNull(),
  /** YYYY-MM-DD: the last day before it turns into a paid charge. */
  endDate: text().notNull(),
  /** What it will cost once it converts (positive), if known. */
  priceCents: integer(),
  interval: text({ enum: ["weekly", "monthly", "quarterly", "annual"] }),
  /** active → cancelled (you stopped it) or kept (you decided to pay). */
  status: text({ enum: ["active", "cancelled", "kept"] })
    .notNull()
    .default("active"),
  /** Where to cancel (a URL or instructions). */
  cancelInfo: text(),
  notes: text(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------
// Savings ledger, DIY replacements, self-hosting costs (Phase 3)
// ---------------------------------------------------------------------------

export const savings = sqliteTable("savings", {
  id: text().primaryKey(),
  kind: text({ enum: ["cancelled", "downgraded", "negotiated", "replaced", "other"] }).notNull(),
  name: text().notNull(),
  /** The recurring charge this saving is about (used to verify it). */
  seriesId: text().references(() => recurringSeries.id, { onDelete: "set null" }),
  /** Monthly cost before and after (positive cents). */
  beforeMonthlyCents: integer().notNull(),
  afterMonthlyCents: integer().notNull().default(0),
  /** YYYY-MM-DD the change took effect. */
  effectiveDate: text().notNull(),
  /** projected → verified (no/lower charge seen) or failed (still charged). */
  status: text({ enum: ["projected", "verified", "failed"] })
    .notNull()
    .default("projected"),
  statusNote: text(),
  verifiedAt: integer({ mode: "timestamp_ms" }),
  notes: text(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const diyProjects = sqliteTable("diy_projects", {
  id: text().primaryKey(),
  /** The paid service being replaced. */
  serviceName: text().notNull(),
  seriesId: text().references(() => recurringSeries.id, { onDelete: "set null" }),
  /** e.g. "Jellyfin" */
  alternative: text().notNull(),
  status: text({ enum: ["idea", "testing", "migrated", "cancelled", "abandoned"] })
    .notNull()
    .default("idea"),
  effort: text({ enum: ["low", "medium", "high"] }),
  /** Extra running cost of the alternative per month (positive cents), beyond shared infrastructure. */
  runningMonthlyCents: integer().notNull().default(0),
  /** Set when the project reaches "cancelled" and a saving is recorded. */
  savingId: text().references(() => savings.id, { onDelete: "set null" }),
  notes: text(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const infraCosts = sqliteTable("infra_costs", {
  id: text().primaryKey(),
  name: text().notNull(),
  kind: text({
    enum: ["power", "hardware", "domain", "hosting", "storage", "software", "other"],
  }).notNull(),
  /** Fixed costs: amount per period (positive cents). */
  amountCents: integer(),
  period: text({ enum: ["monthly", "annual", "once"] }),
  /** Hardware ("once"): spread over this many months. */
  amortizeMonths: integer(),
  /** Power: average draw in watts and price in tenths of a cent per kWh (e.g. 155 = 15.5¢). */
  watts: integer(),
  priceDeciCentsPerKwh: integer(),
  /** YYYY-MM-DD; hardware amortization starts here. */
  startDate: text().notNull(),
  endDate: text(),
  notes: text(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------
// Crypto (Koinly-style portfolio & tax). Quantities are exact decimal strings;
// USD values are integer cents. See docs/DECISIONS.md D-021.
// ---------------------------------------------------------------------------

export const cryptoWallets = sqliteTable("crypto_wallets", {
  id: text().primaryKey(),
  name: text().notNull(),
  /** blockchain (synced from a public address/xpub), exchange, or manual/file-only. */
  kind: text({ enum: ["blockchain", "exchange", "manual"] }).notNull(),
  /** Chain key for blockchain wallets: btc, ltc, doge, zec, eth, xlm, atom, ada, algo… */
  chain: text(),
  /** AES-256-GCM encrypted address or extended public key (an xpub reveals all history). */
  sourceEnc: text(),
  /** Safe display hint, e.g. "zpub6s…D8SH5". */
  sourceHint: text(),
  syncEnabled: integer({ mode: "boolean" }).notNull().default(false),
  status: text({ enum: ["ok", "error", "never"] })
    .notNull()
    .default("never"),
  lastSyncAt: integer({ mode: "timestamp_ms" }),
  lastError: text(),
  /** Provider cursor/checkpoint (not secret). */
  syncCursor: text(),
  /** The user's own notes about this wallet. */
  notes: text(),
  /** Which exchange this is (catalog key, e.g. "kraken"); with sourceEnc, its encrypted API key. */
  exchange: text(),
  /** Kept for history but out of the way (e.g. a closed exchange). */
  archived: integer({ mode: "boolean" }).notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * Tax forms from exchanges (e.g. 1099-DA), per tax year and wallet. The file
 * is encrypted at rest (MUNY_SECRET_KEY); whether the form reports cost basis
 * decides the Form 8949 box.
 */
export const cryptoTaxDocs = sqliteTable(
  "crypto_tax_docs",
  {
    id: text().primaryKey(),
    walletId: text()
      .notNull()
      .references(() => cryptoWallets.id, { onDelete: "cascade" }),
    year: integer().notNull(),
    kind: text().notNull().default("1099-DA"),
    filename: text().notNull(),
    contentType: text().notNull(),
    size: integer().notNull(),
    basisReported: integer({ mode: "boolean" }).notNull().default(true),
    /** Encrypted file bytes. */
    data: blob({ mode: "buffer" }).notNull(),
    uploadedAt: integer().notNull(),
  },
  (t) => [index("crypto_tax_docs_year").on(t.year, t.walletId)],
);

/** One row per wallet sync attempt (the wallet page's "View history"). */
export const cryptoSyncRuns = sqliteTable(
  "crypto_sync_runs",
  {
    id: text().primaryKey(),
    walletId: text()
      .notNull()
      .references(() => cryptoWallets.id, { onDelete: "cascade" }),
    startedAt: integer().notNull(),
    finishedAt: integer().notNull(),
    status: text({ enum: ["ok", "error"] }).notNull(),
    added: integer().notNull().default(0),
    duplicates: integer().notNull().default(0),
    /** Error or notice text (safe to show; never addresses or payloads). */
    message: text(),
  },
  (tbl) => [index("crypto_sync_runs_wallet").on(tbl.walletId, tbl.startedAt)],
);

export const cryptoTxns = sqliteTable(
  "crypto_txns",
  {
    id: text().primaryKey(),
    walletId: text()
      .notNull()
      .references(() => cryptoWallets.id, { onDelete: "cascade" }),
    /** Unix ms (crypto is timestamped, not just dated). */
    at: integer().notNull(),
    /** deposit (in), withdrawal (out), trade (out+in), transfer (between own wallets). */
    type: text({ enum: ["deposit", "withdrawal", "trade", "transfer"] }).notNull(),
    /** reward, staking, airdrop, mining, income, gift, donation, lost, cost, fee_refund, … */
    label: text(),
    sentAsset: text(),
    sentAmount: text(),
    receivedAsset: text(),
    receivedAmount: text(),
    feeAsset: text(),
    feeAmount: text(),
    /** USD value of the transaction at the time (cents), when known. */
    valueCents: integer(),
    feeValueCents: integer(),
    /** Imported cost basis / gain (e.g. from Koinly), kept for reference. */
    importedCostBasisCents: integer(),
    importedGainCents: integer(),
    txHash: text(),
    description: text(),
    /** The other address: who sent a deposit, or where a withdrawal went. */
    counterparty: text(),
    /** Stable id for dedupe: provider id, or a hash of the imported row. */
    externalId: text().notNull(),
    source: text({ enum: ["sync", "import", "manual"] }).notNull(),
    /** The other side of a transfer between your own wallets. */
    transferPairId: text().references((): AnySQLiteColumn => cryptoTxns.id, {
      onDelete: "set null",
    }),
    userModified: integer({ mode: "boolean" }).notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("crypto_txns_external_uq").on(t.walletId, t.externalId),
    index("crypto_txns_at_idx").on(t.at),
  ],
);

/** Daily USD close per asset symbol (decimal string). */
export const cryptoPrices = sqliteTable(
  "crypto_prices",
  {
    asset: text().notNull(),
    /** YYYY-MM-DD (UTC) */
    date: text().notNull(),
    usd: text().notNull(),
    source: text().notNull(),
  },
  (t) => [primaryKey({ columns: [t.asset, t.date] })],
);

// ---------------------------------------------------------------------------
// Investments (stocks, ETFs, funds). Brokerage accounts are `accounts` rows of
// type "investment"; these tables hold what's in them. Quantities and prices
// are exact decimal strings; money is integer cents. See docs/DECISIONS.md D-034.
// ---------------------------------------------------------------------------

export const securities = sqliteTable(
  "securities",
  {
    id: text().primaryKey(),
    /** Ticker (VTI, AAPL); "CASH" for an account's uninvested cash. */
    symbol: text().notNull(),
    name: text().notNull(),
    type: text({
      enum: ["equity", "etf", "mutual_fund", "bond", "option", "cash", "other"],
    }).notNull(),
    currency: text().notNull().default("USD"),
    /** Plaid's security_id, when synced. */
    plaidSecurityId: text(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("securities_symbol_uq").on(t.symbol)],
);

/** What each account holds now, as the broker last reported it. */
export const investmentHoldings = sqliteTable(
  "investment_holdings",
  {
    accountId: text()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    securityId: text()
      .notNull()
      .references(() => securities.id, { onDelete: "cascade" }),
    quantity: text().notNull(),
    /** Price per share (decimal string). */
    price: text(),
    valueCents: integer().notNull(),
    /** Total cost basis the broker reports, when it does. */
    costBasisCents: integer(),
    /** YYYY-MM-DD the broker reported this. */
    asOf: text().notNull(),
    source: text({ enum: ["plaid", "import", "manual"] }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.accountId, t.securityId] })],
);

export const investmentTxns = sqliteTable(
  "investment_txns",
  {
    id: text().primaryKey(),
    accountId: text()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    securityId: text().references(() => securities.id, { onDelete: "set null" }),
    /** YYYY-MM-DD */
    date: text().notNull(),
    type: text({
      enum: [
        "buy",
        "sell",
        "dividend",
        "interest",
        "split",
        "transfer_in",
        "transfer_out",
        "deposit",
        "withdrawal",
        "fee",
        "tax",
        "other",
      ],
    }).notNull(),
    /** Shares, positive (the type says which way). */
    quantity: text(),
    price: text(),
    /** Cash effect: negative for a buy, positive for a sale or dividend. */
    amountCents: integer().notNull(),
    feesCents: integer().notNull().default(0),
    description: text(),
    /** Stable id for dedupe (provider id, or a hash of the imported row). */
    externalId: text().notNull(),
    source: text({ enum: ["plaid", "import", "manual"] }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("investment_txns_external_uq").on(t.accountId, t.externalId),
    index("investment_txns_date_idx").on(t.date),
  ],
);

/** Daily close per security (decimal string), from what brokers report. */
export const securityPrices = sqliteTable(
  "security_prices",
  {
    securityId: text()
      .notNull()
      .references(() => securities.id, { onDelete: "cascade" }),
    /** YYYY-MM-DD */
    date: text().notNull(),
    close: text().notNull(),
    source: text().notNull(),
  },
  (t) => [primaryKey({ columns: [t.securityId, t.date] })],
);

/** Securities to keep an eye on, owned or not (Stocks → Watch list). */
export const watchlist = sqliteTable("watchlist", {
  securityId: text()
    .primaryKey()
    .references(() => securities.id, { onDelete: "cascade" }),
  addedAt: createdAt(),
});

/**
 * What you paid for a holding, entered by you, for brokers that don't report
 * cost basis. Used only while the broker's own figure is missing.
 */
export const holdingCosts = sqliteTable(
  "holding_costs",
  {
    accountId: text()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    securityId: text()
      .notNull()
      .references(() => securities.id, { onDelete: "cascade" }),
    costBasisCents: integer().notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [primaryKey({ columns: [t.accountId, t.securityId] })],
);

/** Company logos (opt-in), fetched once per ticker and kept here. */
export const securityLogos = sqliteTable("security_logos", {
  symbol: text().primaryKey(),
  contentType: text(),
  /** Null when no logo was found (tried again after a while). */
  data: blob({ mode: "buffer" }),
  fetchedAt: integer().notNull(),
});
